// Package jsadapter provides a production JetStream adapter that bridges
// the legacy nats.go v1 pull-subscription API (nats.JetStreamContext) to
// the narrow handlers.JetStreamIface / handlers.JetStreamSub interfaces used
// by the SSE job-progress handler.
//
// The adapters are intentionally thin — they translate types and method
// signatures and nothing else. No business logic lives here.
package jsadapter

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/nats-io/nats.go"

	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/handlers"
)

// ---------- NATSMsgAdapter ----------

// NATSMsgAdapter wraps a raw NATS message payload and an optional ack
// function so it satisfies handlers.NATSMsg.
//
// When constructed from a real *nats.Msg the ackFn calls nats.Msg.Ack.
// When constructed via NewNATSMsgAdapter (test helper) ackFn is a no-op.
type NATSMsgAdapter struct {
	data  []byte
	ackFn func()
}

// NewNATSMsgAdapter constructs a NATSMsgAdapter from a raw payload with a
// no-op Ack. Used in tests and as a building block for fromNatsMsg.
func NewNATSMsgAdapter(data []byte) *NATSMsgAdapter {
	return &NATSMsgAdapter{data: data, ackFn: func() {}}
}

// fromNatsMsg wraps a real *nats.Msg into a NATSMsgAdapter.
func fromNatsMsg(m *nats.Msg) *NATSMsgAdapter {
	return &NATSMsgAdapter{
		data:  m.Data,
		ackFn: func() { _ = m.Ack() },
	}
}

// Data returns the message payload bytes.
func (a *NATSMsgAdapter) Data() []byte { return a.data }

// Ack acknowledges the underlying NATS message (or no-ops if no real message).
func (a *NATSMsgAdapter) Ack() { a.ackFn() }

// ---------- NATSSubscriptionAdapter ----------

// NATSSubscriptionAdapter wraps a *nats.Subscription and adapts its
// Fetch / Unsubscribe methods to the handlers.JetStreamSub interface.
//
// The real nats.Subscription.Fetch signature is
//
//	Fetch(batch int, opts ...nats.PullOpt) ([]*nats.Msg, error)
//
// whereas handlers.JetStreamSub.Fetch is
//
//	Fetch(batch int, timeout time.Duration) ([]handlers.NATSMsg, error)
//
// This adapter bridges the gap by passing the timeout as nats.MaxWait(timeout).
type NATSSubscriptionAdapter struct {
	fetchFn       func(int, time.Duration) ([]handlers.NATSMsg, error)
	unsubscribeFn func() error
}

// NewNATSSubscriptionAdapter wraps a real *nats.Subscription.
func NewNATSSubscriptionAdapter(sub *nats.Subscription) *NATSSubscriptionAdapter {
	return &NATSSubscriptionAdapter{
		fetchFn: func(batch int, timeout time.Duration) ([]handlers.NATSMsg, error) {
			msgs, err := sub.Fetch(batch, nats.MaxWait(timeout))
			if err != nil {
				return nil, translateFetchErr(err)
			}
			out := make([]handlers.NATSMsg, len(msgs))
			for i, m := range msgs {
				out[i] = fromNatsMsg(m)
			}
			return out, nil
		},
		unsubscribeFn: sub.Unsubscribe,
	}
}

// NewNATSSubscriptionAdapterWithFuncs constructs a NATSSubscriptionAdapter
// from explicit function values. Used in unit tests that do not have a real
// *nats.Subscription.
func NewNATSSubscriptionAdapterWithFuncs(
	fetchFn func(int, time.Duration) ([]handlers.NATSMsg, error),
	unsubscribeFn func() error,
) *NATSSubscriptionAdapter {
	return &NATSSubscriptionAdapter{
		fetchFn:       fetchFn,
		unsubscribeFn: unsubscribeFn,
	}
}

// Fetch delegates to the underlying nats.Subscription with MaxWait set to
// timeout, then wraps each returned message in a NATSMsgAdapter.
func (a *NATSSubscriptionAdapter) Fetch(batch int, timeout time.Duration) ([]handlers.NATSMsg, error) {
	return a.fetchFn(batch, timeout)
}

// translateFetchErr maps transport-specific errors that represent an
// ordinary, transient "nothing new yet" condition to handlers.ErrFetchTimeout
// so the SSE loop's error-window budget (see job_progress.go) is spent only
// on genuinely hard failures, not on a NATS/JetStream blip that resolves on
// its own within the loop's own retry cadence:
//
//   - nats.ErrTimeout: the ordinary Fetch-wait-elapsed case.
//   - nats.ErrNoResponders: transient during e.g. a JetStream leader
//     election window (nats.go itself retries no-responders internally for
//     the same reason, see js.go's own "small blips in leadership changes"
//     comment).
//   - nats.ErrConsumerLeadershipChanged: the 409 "Leadership Changed"
//     response emitted mid-election; nats.go still surfaces it to the
//     caller rather than swallowing it, but it is exactly as transient as
//     ErrNoResponders and resolves once the new leader settles.
//   - context.DeadlineExceeded: some nats.go code paths surface the
//     context's own deadline error instead of ErrTimeout for a Fetch that
//     used a caller-supplied context; treated the same as ErrTimeout.
//
// Any other error passes through unchanged as a hard failure.
func translateFetchErr(err error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, nats.ErrTimeout) ||
		errors.Is(err, nats.ErrNoResponders) ||
		errors.Is(err, nats.ErrConsumerLeadershipChanged) ||
		errors.Is(err, context.DeadlineExceeded) {
		return handlers.ErrFetchTimeout
	}
	return err
}

// Unsubscribe delegates to the underlying nats.Subscription.
func (a *NATSSubscriptionAdapter) Unsubscribe() error { return a.unsubscribeFn() }

// ---------- NATSJetStreamAdapter ----------

// NATSJetStreamAdapter adapts nats.JetStreamContext to the
// handlers.JetStreamIface contract.
//
// nats.JetStreamContext.PullSubscribe is:
//
//	PullSubscribe(subj, durable string, opts ...nats.SubOpt) (*nats.Subscription, error)
//
// handlers.JetStreamIface.PullSubscribe is:
//
//	PullSubscribe(subject, durable string, opts ...handlers.JSOpt) (handlers.JetStreamSub, error)
//
// The opts conversion is a no-op for the default call path (no opts are
// passed in production). If callers ever pass functional opts they must be
// concrete *nats.SubOpt values wrapped in a type that also implements
// handlers.JSOpt — a compile-time guard enforces this via the type assertion
// below.
type NATSJetStreamAdapter struct {
	js nats.JetStreamContext
}

// NewNATSJetStreamAdapter wraps a nats.JetStreamContext.
func NewNATSJetStreamAdapter(js nats.JetStreamContext) *NATSJetStreamAdapter {
	return &NATSJetStreamAdapter{js: js}
}

// PullSubscribe adapts JetStreamIface.PullSubscribe to the underlying
// nats.JetStreamContext.PullSubscribe.
//
// handlers.JSOpt is sealed (jsOptTag is unexported), so this adapter only
// ever recognizes known values exported by the handlers package via direct
// interface comparison (e.g. handlers.OptDeliverAll) — it never asserts a
// JSOpt to nats.SubOpt. handlers.JSOpt and nats.SubOpt are unrelated types
// (a plain func type has no jsOptTag method), so that assertion could never
// succeed for any real value; asserting it anyway would be dead code whose
// failure path panics inside the HTTP request goroutine instead of
// returning an ordinary error. An unrecognized option is therefore reported
// as an error, not a panic — see the compile-time interface-satisfaction
// test for why this is reachable only via a future JSOpt value this adapter
// hasn't been taught yet, not via any option handlers.Stream can produce
// today.
func (a *NATSJetStreamAdapter) PullSubscribe(subject, durable string, opts ...handlers.JSOpt) (handlers.JetStreamSub, error) {
	natsOpts := make([]nats.SubOpt, 0, len(opts))
	for _, o := range opts {
		if o == handlers.OptDeliverAll {
			natsOpts = append(natsOpts, nats.DeliverAll())
			continue
		}
		return nil, fmt.Errorf("jsadapter: unrecognized JSOpt %v — adapter does not know how to translate it", o)
	}
	sub, err := a.js.PullSubscribe(subject, durable, natsOpts...)
	if err != nil {
		return nil, err
	}
	return NewNATSSubscriptionAdapter(sub), nil
}


