package jsadapter

import (
	"context"
	"errors"
	"testing"

	"github.com/nats-io/nats.go"

	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/handlers"
)

// TestTranslateFetchErr is the table-driven proof for finding 3's adapter
// half: translateFetchErr must widen its transient-error translation beyond
// nats.ErrTimeout so a JetStream leader election (which can surface as
// nats.ErrNoResponders, the 409 "Leadership Changed" ErrConsumerLeadership
// -Changed, or a context deadline on some code paths) is treated as an
// ordinary "nothing new yet" tick rather than a hard failure that burns the
// SSE handler's error-window budget (job_progress.go).
func TestTranslateFetchErr(t *testing.T) {
	hardErr := errors.New("consumer deleted")

	tests := []struct {
		name string
		in   error
		want error
	}{
		{"nil passes through as nil", nil, nil},
		{"ErrTimeout translates to ErrFetchTimeout", nats.ErrTimeout, handlers.ErrFetchTimeout},
		{"ErrNoResponders translates to ErrFetchTimeout", nats.ErrNoResponders, handlers.ErrFetchTimeout},
		{
			"ErrConsumerLeadershipChanged translates to ErrFetchTimeout",
			nats.ErrConsumerLeadershipChanged,
			handlers.ErrFetchTimeout,
		},
		{
			"context.DeadlineExceeded translates to ErrFetchTimeout",
			context.DeadlineExceeded,
			handlers.ErrFetchTimeout,
		},
		{"an unrelated hard error passes through unchanged", hardErr, hardErr},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := translateFetchErr(tt.in)
			if tt.want == nil {
				if got != nil {
					t.Errorf("translateFetchErr(%v) = %v, want nil", tt.in, got)
				}
				return
			}
			if !errors.Is(got, tt.want) && got != tt.want {
				t.Errorf("translateFetchErr(%v) = %v, want %v", tt.in, got, tt.want)
			}
		})
	}
}


