package jsadapter_test

import (
	"testing"
	"time"

	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/handlers"
	"github.com/zenithflowinc/omnicore-platform/services/range-bff/internal/jsadapter"
)

// TestNATSJetStreamAdapter_ImplementsJetStreamIface verifies at compile time
// that *jsadapter.NATSJetStreamAdapter satisfies the handlers.JetStreamIface
// interface. If the adapter is missing or its method signature is wrong, this
// test file will not compile.
func TestNATSJetStreamAdapter_ImplementsJetStreamIface(t *testing.T) {
	var _ handlers.JetStreamIface = (*jsadapter.NATSJetStreamAdapter)(nil)
}

// TestNATSSubscriptionAdapter_ImplementsJetStreamSub verifies at compile time
// that *jsadapter.NATSSubscriptionAdapter satisfies the handlers.JetStreamSub
// interface.
func TestNATSSubscriptionAdapter_ImplementsJetStreamSub(t *testing.T) {
	var _ handlers.JetStreamSub = (*jsadapter.NATSSubscriptionAdapter)(nil)
}

// TestNATSMsgAdapter_ImplementsNATSMsg verifies at compile time that
// *jsadapter.NATSMsgAdapter satisfies the handlers.NATSMsg interface.
func TestNATSMsgAdapter_ImplementsNATSMsg(t *testing.T) {
	var _ handlers.NATSMsg = (*jsadapter.NATSMsgAdapter)(nil)
}

// TestNATSMsgAdapter_DataReturnsPayload verifies the Data() method returns the
// underlying byte slice unchanged.
func TestNATSMsgAdapter_DataReturnsPayload(t *testing.T) {
	payload := []byte(`{"status":"in_progress"}`)
	adapter := jsadapter.NewNATSMsgAdapter(payload)

	got := adapter.Data()
	if string(got) != string(payload) {
		t.Errorf("Data() = %q, want %q", got, payload)
	}
}

// TestNATSMsgAdapter_AckIsNoopWithoutSubscription verifies that calling
// Ack() on an adapter created without a real subscription (nil ack func)
// does not panic.
func TestNATSMsgAdapter_AckIsNoopWithoutSubscription(t *testing.T) {
	adapter := jsadapter.NewNATSMsgAdapter([]byte(`{}`))
	// Must not panic.
	adapter.Ack()
}

// TestNATSSubscriptionAdapter_UnsubscribeCallsDelegate verifies that
// Unsubscribe() delegates to the provided function.
func TestNATSSubscriptionAdapter_UnsubscribeCallsDelegate(t *testing.T) {
	called := false
	sub := jsadapter.NewNATSSubscriptionAdapterWithFuncs(
		func(_ int, _ time.Duration) ([]handlers.NATSMsg, error) { return nil, nil },
		func() error { called = true; return nil },
	)

	if err := sub.Unsubscribe(); err != nil {
		t.Fatalf("Unsubscribe: %v", err)
	}
	if !called {
		t.Error("Unsubscribe did not call delegate")
	}
}

// TestNATSSubscriptionAdapter_FetchDelegatesMessages verifies that Fetch()
// returns whatever the delegate produces.
func TestNATSSubscriptionAdapter_FetchDelegatesMessages(t *testing.T) {
	msg := jsadapter.NewNATSMsgAdapter([]byte(`{"status":"ok"}`))
	sub := jsadapter.NewNATSSubscriptionAdapterWithFuncs(
		func(_ int, _ time.Duration) ([]handlers.NATSMsg, error) {
			return []handlers.NATSMsg{msg}, nil
		},
		func() error { return nil },
	)

	msgs, err := sub.Fetch(1, time.Second)
	if err != nil {
		t.Fatalf("Fetch: %v", err)
	}
	if len(msgs) != 1 {
		t.Errorf("Fetch returned %d messages, want 1", len(msgs))
	}
}

// TestNATSJetStreamAdapter_UnrecognizedJSOptReturnsErrorNotPanic is the
// finding-7 regression test: handlers.JSOpt is sealed, so nats.SubOpt (a
// plain func type without the unexported jsOptTag method) can never satisfy
// it — the adapter's former `o.(nats.SubOpt)` fallback branch was therefore
// dead code that could only ever hit its failure path, which panicked
// inside the HTTP request goroutine. Any future JSOpt value this adapter
// hasn't been taught to translate (modeled here by
// handlers.OptUnrecognizedForAdapterTests, a second sealed JSOpt minted
// purely for this test) must instead surface as an ordinary error.
func TestNATSJetStreamAdapter_UnrecognizedJSOptReturnsErrorNotPanic(t *testing.T) {
	// nil is a valid nats.JetStreamContext value here: the adapter must
	// reject the unrecognized option before ever touching the underlying
	// JetStream context.
	a := jsadapter.NewNATSJetStreamAdapter(nil)

	defer func() {
		if r := recover(); r != nil {
			t.Fatalf("PullSubscribe panicked on an unrecognized JSOpt: %v", r)
		}
	}()

	_, err := a.PullSubscribe("subject", "", handlers.OptUnrecognizedForAdapterTests)
	if err == nil {
		t.Fatal("expected an error for an unrecognized JSOpt, got nil")
	}
}



